fs = 1000; t = (0:9)'/fs;
x = sin(2*pi*10*t);
[y, tt] = modulate(x, 100, fs);
disp(round(y'*1000)/1000)
disp(tt(1:3)')
y = modulate(x, 100, fs, 'fm');
disp(round(y'*1000)/1000)

A = reshape(1:6, 2, 3);
[y, perm, n] = shiftdata(A, 2);
